/**
 * EventBus — a simple in-memory publish/subscribe system.
 *
 * Services publish named events with arbitrary payloads.
 * Other services subscribe to event names and receive callbacks
 * whenever a matching event is published.
 *
 * No service should import another service directly; all
 * cross-service communication flows through this bus.
 */

export type EventHandler<T = unknown> = (payload: T) => void;

export interface BusEvent<T = unknown> {
  name: string;
  payload: T;
}

export class EventBus {
  // Map from event name → list of handlers
  private readonly handlers: Map<string, EventHandler<unknown>[]> = new Map();

  /**
   * Subscribe to an event by name.
   * Returns an unsubscribe function for cleanup.
   */
  subscribe<T>(eventName: string, handler: EventHandler<T>): () => void {
    if (!this.handlers.has(eventName)) {
      this.handlers.set(eventName, []);
    }
    // Cast is safe: we only call T-typed handlers with T-typed payloads
    this.handlers.get(eventName)!.push(handler as EventHandler<unknown>);

    return () => {
      const list = this.handlers.get(eventName);
      if (list) {
        const idx = list.indexOf(handler as EventHandler<unknown>);
        if (idx !== -1) list.splice(idx, 1);
      }
    };
  }

  /**
   * Publish an event to all current subscribers.
   * Handlers are called synchronously in subscription order.
   */
  publish<T>(eventName: string, payload: T): void {
    const list = this.handlers.get(eventName);
    if (!list || list.length === 0) return;
    // Snapshot the list so mid-iteration unsubscribes are safe
    for (const handler of [...list]) {
      handler(payload as unknown);
    }
  }

  /** Return the number of subscribers for a given event (useful for tests/debug). */
  subscriberCount(eventName: string): number {
    return this.handlers.get(eventName)?.length ?? 0;
  }
}

/**
 * Shared domain types used across services and the router.
 * Services own their data; these types are the shared language.
 */

// ─── Users ────────────────────────────────────────────────────────────────────

export interface User {
  id: string;
  name: string;
  email: string;
}

export interface CreateUserInput {
  name: string;
  email: string;
}

export interface UpdateUserInput {
  name?: string;
  email?: string;
}

// ─── Projects ─────────────────────────────────────────────────────────────────

export interface Project {
  id: string;
  name: string;
  description: string;
  memberIds: string[];
}

export interface CreateProjectInput {
  name: string;
  description: string;
}

export interface UpdateProjectInput {
  name?: string;
  description?: string;
}

// ─── Tasks ────────────────────────────────────────────────────────────────────

export type TaskStatus = "todo" | "in-progress" | "done";

export interface Task {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  assigneeId: string | null;
  projectId: string;
}

export interface CreateTaskInput {
  title: string;
  description: string;
  projectId: string;
}

export interface UpdateTaskInput {
  title?: string;
  description?: string;
}

// ─── Comments ─────────────────────────────────────────────────────────────────

export interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: string; // ISO-8601 timestamp
}

export interface CreateCommentInput {
  taskId: string;
  authorId: string;
  body: string;
}

// ─── Notifications ────────────────────────────────────────────────────────────

export interface Notification {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  createdAt: string; // ISO-8601 timestamp
}

// ─── Event payloads ───────────────────────────────────────────────────────────

export interface TaskAssignedPayload {
  taskId: string;
  taskTitle: string;
  assigneeId: string;
  projectId: string;
}

export interface TaskStatusChangedPayload {
  taskId: string;
  taskTitle: string;
  assigneeId: string | null;
  projectId: string;
  oldStatus: TaskStatus;
  newStatus: TaskStatus;
}

export interface CommentAddedPayload {
  commentId: string;
  taskId: string;
  taskTitle: string;
  authorId: string;
  assigneeId: string | null; // notified if different from author
  body: string;
}

// ─── HTTP helpers ─────────────────────────────────────────────────────────────

export interface ApiError {
  error: string;
}

/**
 * UserService — owns all user data.
 *
 * Provides full CRUD for users.  No other service stores user
 * records; if another service needs user information it must
 * receive it through event payloads or the router must
 * orchestrate the lookup.
 */

import { randomUUID } from "crypto";
import type { User, CreateUserInput, UpdateUserInput } from "../types.js";

export class UserService {
  private readonly users: Map<string, User> = new Map();

  // ── Create ────────────────────────────────────────────────────────────────

  createUser(input: CreateUserInput): User {
    if (!input.name || input.name.trim() === "") {
      throw new Error("User name is required.");
    }
    if (!input.email || input.email.trim() === "") {
      throw new Error("User email is required.");
    }
    if (!this.isValidEmail(input.email)) {
      throw new Error(`"${input.email}" is not a valid email address.`);
    }
    if (this.findByEmail(input.email)) {
      throw new Error(`A user with email "${input.email}" already exists.`);
    }

    const user: User = {
      id: randomUUID(),
      name: input.name.trim(),
      email: input.email.trim().toLowerCase(),
    };

    this.users.set(user.id, user);
    return user;
  }

  // ── Read ──────────────────────────────────────────────────────────────────

  getUser(id: string): User {
    const user = this.users.get(id);
    if (!user) throw new Error(`User "${id}" not found.`);
    return user;
  }

  listUsers(): User[] {
    return [...this.users.values()];
  }

  // ── Update ────────────────────────────────────────────────────────────────

  updateUser(id: string, input: UpdateUserInput): User {
    const user = this.getUser(id);

    if (input.email !== undefined) {
      if (!this.isValidEmail(input.email)) {
        throw new Error(`"${input.email}" is not a valid email address.`);
      }
      const existing = this.findByEmail(input.email);
      if (existing && existing.id !== id) {
        throw new Error(`A user with email "${input.email}" already exists.`);
      }
      user.email = input.email.trim().toLowerCase();
    }

    if (input.name !== undefined) {
      if (input.name.trim() === "") throw new Error("User name cannot be empty.");
      user.name = input.name.trim();
    }

    return user;
  }

  // ── Delete ────────────────────────────────────────────────────────────────

  deleteUser(id: string): void {
    if (!this.users.has(id)) throw new Error(`User "${id}" not found.`);
    this.users.delete(id);
  }

  // ── Helpers ───────────────────────────────────────────────────────────────

  /** Returns true if the user id exists (used by other services via the router). */
  userExists(id: string): boolean {
    return this.users.has(id);
  }

  private findByEmail(email: string): User | undefined {
    const lower = email.trim().toLowerCase();
    for (const user of this.users.values()) {
      if (user.email === lower) return user;
    }
    return undefined;
  }

  private isValidEmail(email: string): boolean {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim());
  }
}

/**
 * ProjectService — owns all project data.
 *
 * Manages CRUD for projects and the membership list.
 * Member validation (does the user ID actually exist?) is the
 * responsibility of the router, which can call the UserService
 * before delegating to this service.
 */

import { randomUUID } from "crypto";
import type {
  Project,
  CreateProjectInput,
  UpdateProjectInput,
} from "../types.js";

export class ProjectService {
  private readonly projects: Map<string, Project> = new Map();

  // ── Create ────────────────────────────────────────────────────────────────

  createProject(input: CreateProjectInput): Project {
    if (!input.name || input.name.trim() === "") {
      throw new Error("Project name is required.");
    }

    const project: Project = {
      id: randomUUID(),
      name: input.name.trim(),
      description: (input.description ?? "").trim(),
      memberIds: [],
    };

    this.projects.set(project.id, project);
    return project;
  }

  // ── Read ──────────────────────────────────────────────────────────────────

  getProject(id: string): Project {
    const project = this.projects.get(id);
    if (!project) throw new Error(`Project "${id}" not found.`);
    return project;
  }

  listProjects(): Project[] {
    return [...this.projects.values()];
  }

  // ── Update ────────────────────────────────────────────────────────────────

  updateProject(id: string, input: UpdateProjectInput): Project {
    const project = this.getProject(id);

    if (input.name !== undefined) {
      if (input.name.trim() === "") throw new Error("Project name cannot be empty.");
      project.name = input.name.trim();
    }
    if (input.description !== undefined) {
      project.description = input.description.trim();
    }

    return project;
  }

  // ── Delete ────────────────────────────────────────────────────────────────

  deleteProject(id: string): void {
    if (!this.projects.has(id)) throw new Error(`Project "${id}" not found.`);
    this.projects.delete(id);
  }

  // ── Membership ────────────────────────────────────────────────────────────

  /**
   * Add a user to a project's member list.
   * The router is responsible for confirming the user exists first.
   */
  addMember(projectId: string, userId: string): Project {
    const project = this.getProject(projectId);
    if (project.memberIds.includes(userId)) {
      throw new Error(`User "${userId}" is already a member of project "${projectId}".`);
    }
    project.memberIds.push(userId);
    return project;
  }

  /**
   * Remove a user from a project's member list.
   */
  removeMember(projectId: string, userId: string): Project {
    const project = this.getProject(projectId);
    const idx = project.memberIds.indexOf(userId);
    if (idx === -1) {
      throw new Error(`User "${userId}" is not a member of project "${projectId}".`);
    }
    project.memberIds.splice(idx, 1);
    return project;
  }

  // ── Helpers ───────────────────────────────────────────────────────────────

  projectExists(id: string): boolean {
    return this.projects.has(id);
  }
}

/**
 * TaskService — owns all task data.
 *
 * Enforces valid status transitions:
 *   todo → in-progress → done
 *
 * Publishes events to the EventBus so that other services
 * (e.g. NotificationService) can react without being coupled
 * to the TaskService directly.
 */

import { randomUUID } from "crypto";
import type { EventBus } from "../event-bus.js";
import type {
  Task,
  TaskStatus,
  CreateTaskInput,
  UpdateTaskInput,
  TaskAssignedPayload,
  TaskStatusChangedPayload,
} from "../types.js";

/** Ordered status chain — earlier index = earlier in lifecycle. */
const STATUS_ORDER: TaskStatus[] = ["todo", "in-progress", "done"];

function statusRank(s: TaskStatus): number {
  return STATUS_ORDER.indexOf(s);
}

export class TaskService {
  private readonly tasks: Map<string, Task> = new Map();

  constructor(private readonly eventBus: EventBus) {}

  // ── Create ────────────────────────────────────────────────────────────────

  /**
   * Create a new task in the given project.
   * The router is responsible for verifying the project exists.
   */
  createTask(input: CreateTaskInput): Task {
    if (!input.title || input.title.trim() === "") {
      throw new Error("Task title is required.");
    }
    if (!input.projectId) {
      throw new Error("Task projectId is required.");
    }

    const task: Task = {
      id: randomUUID(),
      title: input.title.trim(),
      description: (input.description ?? "").trim(),
      status: "todo",
      assigneeId: null,
      projectId: input.projectId,
    };

    this.tasks.set(task.id, task);
    return task;
  }

  // ── Read ──────────────────────────────────────────────────────────────────

  getTask(id: string): Task {
    const task = this.tasks.get(id);
    if (!task) throw new Error(`Task "${id}" not found.`);
    return task;
  }

  /**
   * List all tasks, optionally filtering by projectId.
   */
  listTasks(projectId?: string): Task[] {
    const all = [...this.tasks.values()];
    return projectId ? all.filter((t) => t.projectId === projectId) : all;
  }

  // ── Update ────────────────────────────────────────────────────────────────

  updateTask(id: string, input: UpdateTaskInput): Task {
    const task = this.getTask(id);

    if (input.title !== undefined) {
      if (input.title.trim() === "") throw new Error("Task title cannot be empty.");
      task.title = input.title.trim();
    }
    if (input.description !== undefined) {
      task.description = input.description.trim();
    }

    return task;
  }

  // ── Delete ────────────────────────────────────────────────────────────────

  deleteTask(id: string): void {
    if (!this.tasks.has(id)) throw new Error(`Task "${id}" not found.`);
    this.tasks.delete(id);
  }

  // ── Status transitions ────────────────────────────────────────────────────

  /**
   * Advance (or validate) a status transition.
   * Only forward transitions are allowed; attempting to move
   * backwards (e.g. done → todo) throws an error.
   */
  setStatus(id: string, newStatus: TaskStatus): Task {
    const task = this.getTask(id);
    const currentRank = statusRank(task.status);
    const newRank = statusRank(newStatus);

    if (newRank === -1) {
      throw new Error(
        `Invalid status "${newStatus}". Valid values: ${STATUS_ORDER.join(", ")}.`
      );
    }

    if (newRank === currentRank) {
      // No-op — already in that state
      return task;
    }

    if (newRank < currentRank) {
      throw new Error(
        `Invalid status transition: cannot move from "${task.status}" to "${newStatus}".`
      );
    }

    const oldStatus = task.status;
    task.status = newStatus;

    const payload: TaskStatusChangedPayload = {
      taskId: task.id,
      taskTitle: task.title,
      assigneeId: task.assigneeId,
      projectId: task.projectId,
      oldStatus,
      newStatus,
    };
    this.eventBus.publish("task.statusChanged", payload);

    return task;
  }

  // ── Assignment ────────────────────────────────────────────────────────────

  /**
   * Assign (or re-assign) a task to a user.
   * The router is responsible for confirming the user exists.
   */
  assignTask(id: string, userId: string): Task {
    const task = this.getTask(id);
    task.assigneeId = userId;

    const payload: TaskAssignedPayload = {
      taskId: task.id,
      taskTitle: task.title,
      assigneeId: userId,
      projectId: task.projectId,
    };
    this.eventBus.publish("task.assigned", payload);

    return task;
  }

  // ── Helpers ───────────────────────────────────────────────────────────────

  taskExists(id: string): boolean {
    return this.tasks.has(id);
  }

  /** Delete all tasks belonging to a project (called when a project is deleted). */
  deleteTasksByProject(projectId: string): void {
    for (const [id, task] of this.tasks) {
      if (task.projectId === projectId) this.tasks.delete(id);
    }
  }
}

/**
 * CommentService — owns all comment data.
 *
 * Comments belong to tasks.  When a comment is created the service
 * publishes a "comment.added" event so the NotificationService can
 * alert the task's assignee without any direct coupling.
 *
 * Note: resolving the task's current assignee is done by the router
 * (which has access to the TaskService) before calling createComment,
 * and is passed in as part of the input so this service stays decoupled.
 */

import { randomUUID } from "crypto";
import type { EventBus } from "../event-bus.js";
import type {
  Comment,
  CreateCommentInput,
  CommentAddedPayload,
} from "../types.js";

/** Extended input that carries runtime context the event needs. */
export interface CreateCommentContext extends CreateCommentInput {
  taskTitle: string;
  assigneeId: string | null;
}

export class CommentService {
  private readonly comments: Map<string, Comment> = new Map();

  constructor(private readonly eventBus: EventBus) {}

  // ── Create ────────────────────────────────────────────────────────────────

  createComment(ctx: CreateCommentContext): Comment {
    if (!ctx.taskId) throw new Error("Comment taskId is required.");
    if (!ctx.authorId) throw new Error("Comment authorId is required.");
    if (!ctx.body || ctx.body.trim() === "") {
      throw new Error("Comment body is required.");
    }

    const comment: Comment = {
      id: randomUUID(),
      taskId: ctx.taskId,
      authorId: ctx.authorId,
      body: ctx.body.trim(),
      createdAt: new Date().toISOString(),
    };

    this.comments.set(comment.id, comment);

    const payload: CommentAddedPayload = {
      commentId: comment.id,
      taskId: comment.taskId,
      taskTitle: ctx.taskTitle,
      authorId: comment.authorId,
      assigneeId: ctx.assigneeId,
      body: comment.body,
    };
    this.eventBus.publish("comment.added", payload);

    return comment;
  }

  // ── Read ──────────────────────────────────────────────────────────────────

  getComment(id: string): Comment {
    const comment = this.comments.get(id);
    if (!comment) throw new Error(`Comment "${id}" not found.`);
    return comment;
  }

  /**
   * List all comments, optionally filtered by taskId.
   * Results are sorted oldest-first.
   */
  listComments(taskId?: string): Comment[] {
    const all = [...this.comments.values()];
    const filtered = taskId ? all.filter((c) => c.taskId === taskId) : all;
    return filtered.sort(
      (a, b) => new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime()
    );
  }

  // ── Delete ────────────────────────────────────────────────────────────────

  deleteComment(id: string): void {
    if (!this.comments.has(id)) throw new Error(`Comment "${id}" not found.`);
    this.comments.delete(id);
  }

  /** Remove all comments for a task (called when the task is deleted). */
  deleteCommentsByTask(taskId: string): void {
    for (const [id, comment] of this.comments) {
      if (comment.taskId === taskId) this.comments.delete(id);
    }
  }
}

/**
 * NotificationService — owns all notification data.
 *
 * Subscribes to domain events published by other services and creates
 * user-facing notifications.  It never calls other services directly.
 *
 * Subscribed events:
 *   • task.assigned      → notify the new assignee
 *   • task.statusChanged → notify the assignee (if any) of the new status
 *   • comment.added      → notify the task assignee when someone else comments
 */

import { randomUUID } from "crypto";
import type { EventBus } from "../event-bus.js";
import type {
  Notification,
  TaskAssignedPayload,
  TaskStatusChangedPayload,
  CommentAddedPayload,
} from "../types.js";

export class NotificationService {
  private readonly notifications: Map<string, Notification> = new Map();

  constructor(private readonly eventBus: EventBus) {
    this.registerSubscriptions();
  }

  // ── Event subscriptions ───────────────────────────────────────────────────

  private registerSubscriptions(): void {
    this.eventBus.subscribe<TaskAssignedPayload>(
      "task.assigned",
      (payload) => {
        this.createNotification(
          payload.assigneeId,
          `You have been assigned to task "${payload.taskTitle}".`
        );
      }
    );

    this.eventBus.subscribe<TaskStatusChangedPayload>(
      "task.statusChanged",
      (payload) => {
        if (!payload.assigneeId) return; // No one to notify
        this.createNotification(
          payload.assigneeId,
          `Task "${payload.taskTitle}" status changed from "${payload.oldStatus}" to "${payload.newStatus}".`
        );
      }
    );

    this.eventBus.subscribe<CommentAddedPayload>(
      "comment.added",
      (payload) => {
        // Only notify the assignee if they are different from the comment author
        if (!payload.assigneeId) return;
        if (payload.assigneeId === payload.authorId) return;
        this.createNotification(
          payload.assigneeId,
          `A new comment was added to task "${payload.taskTitle}": "${this.truncate(payload.body, 80)}"`
        );
      }
    );
  }

  // ── Create ────────────────────────────────────────────────────────────────

  private createNotification(userId: string, message: string): Notification {
    const notification: Notification = {
      id: randomUUID(),
      userId,
      message,
      read: false,
      createdAt: new Date().toISOString(),
    };
    this.notifications.set(notification.id, notification);
    return notification;
  }

  // ── Read ──────────────────────────────────────────────────────────────────

  getNotification(id: string): Notification {
    const n = this.notifications.get(id);
    if (!n) throw new Error(`Notification "${id}" not found.`);
    return n;
  }

  /**
   * List notifications, optionally filtered to a specific user.
   * Results are sorted newest-first.
   */
  listNotifications(userId?: string): Notification[] {
    const all = [...this.notifications.values()];
    const filtered = userId ? all.filter((n) => n.userId === userId) : all;
    return filtered.sort(
      (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
    );
  }

  // ── Mark as read ──────────────────────────────────────────────────────────

  markAsRead(id: string): Notification {
    const n = this.getNotification(id);
    n.read = true;
    return n;
  }

  // ── Helpers ───────────────────────────────────────────────────────────────

  private truncate(text: string, max: number): string {
    return text.length <= max ? text : text.slice(0, max - 1) + "…";
  }
}

/**
 * ApiRouter — the single HTTP entry point for the application.
 *
 * Parses incoming requests, routes them to the correct service
 * method, and serialises the response as JSON.  It is the ONLY
 * component that calls service methods directly.  Services never
 * handle HTTP themselves.
 *
 * Route summary
 * ─────────────
 * Users
 *   GET    /users
 *   POST   /users
 *   GET    /users/:id
 *   PUT    /users/:id
 *   DELETE /users/:id
 *
 * Projects
 *   GET    /projects
 *   POST   /projects
 *   GET    /projects/:id
 *   PUT    /projects/:id
 *   DELETE /projects/:id
 *   POST   /projects/:id/members        body: { userId }
 *   DELETE /projects/:id/members/:uid
 *
 * Tasks
 *   GET    /tasks[?projectId=…]
 *   POST   /tasks
 *   GET    /tasks/:id
 *   PUT    /tasks/:id
 *   DELETE /tasks/:id
 *   PUT    /tasks/:id/status            body: { status }
 *   PUT    /tasks/:id/assign            body: { userId }
 *
 * Comments
 *   GET    /comments[?taskId=…]
 *   POST   /comments
 *   GET    /comments/:id
 *   DELETE /comments/:id
 *
 * Notifications
 *   GET    /notifications[?userId=…]
 *   PUT    /notifications/:id/read
 */

import type { IncomingMessage, ServerResponse } from "http";
import type { UserService } from "./services/user-service.js";
import type { ProjectService } from "./services/project-service.js";
import type { TaskService } from "./services/task-service.js";
import type { CommentService } from "./services/comment-service.js";
import type { NotificationService } from "./services/notification-service.js";
import type { TaskStatus } from "./types.js";

// ── Tiny URL helpers (no external deps) ──────────────────────────────────────

/** Split a path into clean, non-empty segments. */
function segments(path: string): string[] {
  return path.split("/").filter(Boolean);
}

/** Parse the query string from a URL into a plain record. */
function parseQuery(url: string): Record<string, string> {
  const idx = url.indexOf("?");
  if (idx === -1) return {};
  const qs = url.slice(idx + 1);
  const result: Record<string, string> = {};
  for (const part of qs.split("&")) {
    const [k, v] = part.split("=");
    if (k) result[decodeURIComponent(k)] = decodeURIComponent(v ?? "");
  }
  return result;
}

// ── Body reader ───────────────────────────────────────────────────────────────

function readBody(req: IncomingMessage): Promise<unknown> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    req.on("data", (chunk: Buffer) => chunks.push(chunk));
    req.on("end", () => {
      const raw = Buffer.concat(chunks).toString("utf8");
      if (!raw) {
        resolve({});
        return;
      }
      try {
        resolve(JSON.parse(raw));
      } catch {
        reject(new Error("Request body is not valid JSON."));
      }
    });
    req.on("error", reject);
  });
}

// ── Response helpers ──────────────────────────────────────────────────────────

function send(res: ServerResponse, statusCode: number, body: unknown): void {
  const json = JSON.stringify(body, null, 2);
  res.writeHead(statusCode, {
    "Content-Type": "application/json",
    "Content-Length": Buffer.byteLength(json),
  });
  res.end(json);
}

function ok(res: ServerResponse, body: unknown): void {
  send(res, 200, body);
}

function created(res: ServerResponse, body: unknown): void {
  send(res, 201, body);
}

function noContent(res: ServerResponse): void {
  res.writeHead(204);
  res.end();
}

function badRequest(res: ServerResponse, message: string): void {
  send(res, 400, { error: message });
}

function notFound(res: ServerResponse, message = "Not found."): void {
  send(res, 404, { error: message });
}

function methodNotAllowed(res: ServerResponse): void {
  send(res, 405, { error: "Method not allowed." });
}

function serverError(res: ServerResponse, err: unknown): void {
  const message = err instanceof Error ? err.message : "Internal server error.";
  send(res, 500, { error: message });
}

// ─────────────────────────────────────────────────────────────────────────────

export class ApiRouter {
  constructor(
    private readonly userService: UserService,
    private readonly projectService: ProjectService,
    private readonly taskService: TaskService,
    private readonly commentService: CommentService,
    private readonly notificationService: NotificationService
  ) {}

  async handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
    const method = req.method?.toUpperCase() ?? "GET";
    const rawUrl = req.url ?? "/";
    const pathOnly = rawUrl.split("?")[0];
    const segs = segments(pathOnly);
    const query = parseQuery(rawUrl);

    try {
      // ── /users[/:id] ───────────────────────────────────────────────────────
      if (segs[0] === "users") {
        await this.handleUsers(method, segs, query, req, res);

      // ── /projects[/:id[/members[/:uid]]] ──────────────────────────────────
      } else if (segs[0] === "projects") {
        await this.handleProjects(method, segs, query, req, res);

      // ── /tasks[/:id[/status|assign]] ──────────────────────────────────────
      } else if (segs[0] === "tasks") {
        await this.handleTasks(method, segs, query, req, res);

      // ── /comments[/:id] ───────────────────────────────────────────────────
      } else if (segs[0] === "comments") {
        await this.handleComments(method, segs, query, req, res);

      // ── /notifications[/:id/read] ─────────────────────────────────────────
      } else if (segs[0] === "notifications") {
        await this.handleNotifications(method, segs, query, req, res);

      } else {
        notFound(res, `No route for "${rawUrl}".`);
      }
    } catch (err) {
      // Surface validation/not-found errors thrown by services
      if (err instanceof Error) {
        const msg = err.message.toLowerCase();
        if (msg.includes("not found")) {
          notFound(res, err.message);
        } else {
          // Treat other service errors as bad requests (validation failures)
          badRequest(res, err.message);
        }
      } else {
        serverError(res, err);
      }
    }
  }

  // ── Users ─────────────────────────────────────────────────────────────────

  private async handleUsers(
    method: string,
    segs: string[],
    _query: Record<string, string>,
    req: IncomingMessage,
    res: ServerResponse
  ): Promise<void> {
    const id = segs[1]; // may be undefined

    if (!id) {
      // /users
      if (method === "GET") {
        ok(res, this.userService.listUsers());
      } else if (method === "POST") {
        const body = (await readBody(req)) as Record<string, unknown>;
        const user = this.userService.createUser({
          name: String(body.name ?? ""),
          email: String(body.email ?? ""),
        });
        created(res, user);
      } else {
        methodNotAllowed(res);
      }
      return;
    }

    // /users/:id
    if (method === "GET") {
      ok(res, this.userService.getUser(id));
    } else if (method === "PUT") {
      const body = (await readBody(req)) as Record<string, unknown>;
      const updated = this.userService.updateUser(id, {
        name: body.name !== undefined ? String(body.name) : undefined,
        email: body.email !== undefined ? String(body.email) : undefined,
      });
      ok(res, updated);
    } else if (method === "DELETE") {
      this.userService.deleteUser(id);
      noContent(res);
    } else {
      methodNotAllowed(res);
    }
  }

  // ── Projects ──────────────────────────────────────────────────────────────

  private async handleProjects(
    method: string,
    segs: string[],
    _query: Record<string, string>,
    req: IncomingMessage,
    res: ServerResponse
  ): Promise<void> {
    const id = segs[1];       // project id
    const sub = segs[2];      // "members" or undefined
    const memberId = segs[3]; // specific member uid or undefined

    if (!id) {
      // /projects
      if (method === "GET") {
        ok(res, this.projectService.listProjects());
      } else if (method === "POST") {
        const body = (await readBody(req)) as Record<string, unknown>;
        const project = this.projectService.createProject({
          name: String(body.name ?? ""),
          description: String(body.description ?? ""),
        });
        created(res, project);
      } else {
        methodNotAllowed(res);
      }
      return;
    }

    if (!sub) {
      // /projects/:id
      if (method === "GET") {
        ok(res, this.projectService.getProject(id));
      } else if (method === "PUT") {
        const body = (await readBody(req)) as Record<string, unknown>;
        const updated = this.projectService.updateProject(id, {
          name: body.name !== undefined ? String(body.name) : undefined,
          description: body.description !== undefined ? String(body.description) : undefined,
        });
        ok(res, updated);
      } else if (method === "DELETE") {
        // Cascade: remove tasks (and implicitly comments) for this project
        this.taskService.deleteTasksByProject(id);
        this.projectService.deleteProject(id);
        noContent(res);
      } else {
        methodNotAllowed(res);
      }
      return;
    }

    if (sub !== "members") {
      notFound(res, `Unknown sub-resource "${sub}".`);
      return;
    }

    if (!memberId) {
      // /projects/:id/members
      if (method === "POST") {
        const body = (await readBody(req)) as Record<string, unknown>;
        const userId = String(body.userId ?? "");
        if (!userId) {
          badRequest(res, "userId is required.");
          return;
        }
        // Validate user exists before mutating project
        this.userService.getUser(userId); // throws if missing
        const project = this.projectService.addMember(id, userId);
        ok(res, project);
      } else {
        methodNotAllowed(res);
      }
      return;
    }

    // /projects/:id/members/:uid
    if (method === "DELETE") {
      const project = this.projectService.removeMember(id, memberId);
      ok(res, project);
    } else {
      methodNotAllowed(res);
    }
  }

  // ── Tasks ─────────────────────────────────────────────────────────────────

  private async handleTasks(
    method: string,
    segs: string[],
    query: Record<string, string>,
    req: IncomingMessage,
    res: ServerResponse
  ): Promise<void> {
    const id = segs[1];   // task id
    const sub = segs[2];  // "status" | "assign" | undefined

    if (!id) {
      // /tasks[?projectId=…]
      if (method === "GET") {
        ok(res, this.taskService.listTasks(query.projectId));
      } else if (method === "POST") {
        const body = (await readBody(req)) as Record<string, unknown>;
        const projectId = String(body.projectId ?? "");
        if (!projectId) {
          badRequest(res, "projectId is required.");
          return;
        }
        // Validate project exists before creating task
        this.projectService.getProject(projectId); // throws if missing
        const task = this.taskService.createTask({
          title: String(body.title ?? ""),
          description: String(body.description ?? ""),
          projectId,
        });
        created(res, task);
      } else {
        methodNotAllowed(res);
      }
      return;
    }

    if (!sub) {
      // /tasks/:id
      if (method === "GET") {
        ok(res, this.taskService.getTask(id));
      } else if (method === "PUT") {
        const body = (await readBody(req)) as Record<string, unknown>;
        const updated = this.taskService.updateTask(id, {
          title: body.title !== undefined ? String(body.title) : undefined,
          description: body.description !== undefined ? String(body.description) : undefined,
        });
        ok(res, updated);
      } else if (method === "DELETE") {
        // Cascade: remove comments for this task
        this.commentService.deleteCommentsByTask(id);
        this.taskService.deleteTask(id);
        noContent(res);
      } else {
        methodNotAllowed(res);
      }
      return;
    }

    // /tasks/:id/status
    if (sub === "status") {
      if (method !== "PUT") { methodNotAllowed(res); return; }
      const body = (await readBody(req)) as Record<string, unknown>;
      const status = String(body.status ?? "") as TaskStatus;
      const updated = this.taskService.setStatus(id, status);
      ok(res, updated);
      return;
    }

    // /tasks/:id/assign
    if (sub === "assign") {
      if (method !== "PUT") { methodNotAllowed(res); return; }
      const body = (await readBody(req)) as Record<string, unknown>;
      const userId = String(body.userId ?? "");
      if (!userId) {
        badRequest(res, "userId is required.");
        return;
      }
      // Validate user exists
      this.userService.getUser(userId); // throws if missing
      const updated = this.taskService.assignTask(id, userId);
      ok(res, updated);
      return;
    }

    notFound(res, `Unknown task sub-resource "${sub}".`);
  }

  // ── Comments ──────────────────────────────────────────────────────────────

  private async handleComments(
    method: string,
    segs: string[],
    query: Record<string, string>,
    req: IncomingMessage,
    res: ServerResponse
  ): Promise<void> {
    const id = segs[1];

    if (!id) {
      // /comments[?taskId=…]
      if (method === "GET") {
        ok(res, this.commentService.listComments(query.taskId));
      } else if (method === "POST") {
        const body = (await readBody(req)) as Record<string, unknown>;
        const taskId = String(body.taskId ?? "");
        const authorId = String(body.authorId ?? "");

        if (!taskId) { badRequest(res, "taskId is required."); return; }
        if (!authorId) { badRequest(res, "authorId is required."); return; }

        // Validate task and author exist; retrieve context for event payload
        const task = this.taskService.getTask(taskId); // throws if missing
        this.userService.getUser(authorId);             // throws if missing

        const comment = this.commentService.createComment({
          taskId,
          authorId,
          body: String(body.body ?? ""),
          taskTitle: task.title,
          assigneeId: task.assigneeId,
        });
        created(res, comment);
      } else {
        methodNotAllowed(res);
      }
      return;
    }

    // /comments/:id
    if (method === "GET") {
      ok(res, this.commentService.getComment(id));
    } else if (method === "DELETE") {
      this.commentService.deleteComment(id);
      noContent(res);
    } else {
      methodNotAllowed(res);
    }
  }

  // ── Notifications ─────────────────────────────────────────────────────────

  private async handleNotifications(
    method: string,
    segs: string[],
    query: Record<string, string>,
    _req: IncomingMessage,
    res: ServerResponse
  ): Promise<void> {
    const id = segs[1];   // notification id
    const sub = segs[2];  // "read"

    if (!id) {
      // /notifications[?userId=…]
      if (method === "GET") {
        ok(res, this.notificationService.listNotifications(query.userId));
      } else {
        methodNotAllowed(res);
      }
      return;
    }

    // /notifications/:id/read
    if (sub === "read") {
      if (method !== "PUT") { methodNotAllowed(res); return; }
      const updated = this.notificationService.markAsRead(id);
      ok(res, updated);
      return;
    }

    // /notifications/:id (no sub-resource other than "read" is supported)
    if (!sub) {
      if (method === "GET") {
        ok(res, this.notificationService.getNotification(id));
      } else {
        methodNotAllowed(res);
      }
      return;
    }

    notFound(res, `Unknown notification sub-resource "${sub}".`);
  }
}

/**
 * main.ts — application entry point.
 *
 * Wires all services together, registers event subscriptions (via
 * the NotificationService constructor), attaches the router, and
 * starts the HTTP server.
 *
 * Usage:
 *   npx tsx src/main.ts
 */

import http from "http";
import { EventBus } from "./event-bus.js";
import { UserService } from "./services/user-service.js";
import { ProjectService } from "./services/project-service.js";
import { TaskService } from "./services/task-service.js";
import { CommentService } from "./services/comment-service.js";
import { NotificationService } from "./services/notification-service.js";
