});

server.listen(PORT, () => {
  console.log(`Task Management API running on http://localhost:${PORT}`);
  console.log("Press Ctrl+C to stop.");
});

server.on("error", (err) => {
  console.error("Server error:", err);
  process.exit(1);
});

